NEDOP = "North East Derbyshire District Council"

def ned(name, area, pc, op=NEDOP, extra=None, desc=None):
    src = [NED] + ([extra] if extra else [])
    return dict(n=name, a=area, d="North East Derbyshire", op=op, src=src, pc=pc,
                desc=desc or f"Play area on North East Derbyshire District Council's list of play areas it inspects and maintains, some of which belong to parish councils.",
                note="The council's list dates from January 2021")

def eck(name, area, pc, slug, desc):
    return ned(name, area, pc, op="Eckington Parish Council (inspected by North East Derbyshire District Council)",
               extra=(f"Eckington Parish Council: {name}", f"https://www.eckington-pc.gov.uk/{slug}"), desc=desc)

